struct OptionScore{ name:&'static str, strategic_fit:f64, impact:f64, feasibility:f64, risk_control:f64, learning_value:f64, option_value:f64, ethical_resilience:f64, evidence_confidence:f64 }
fn score(o:&OptionScore)->f64{0.16*o.strategic_fit+0.16*o.impact+0.12*o.feasibility+0.12*o.risk_control+0.14*o.learning_value+0.12*o.option_value+0.12*o.ethical_resilience+0.06*o.evidence_confidence}
fn main(){let options=vec![OptionScore{name:"Core Process Improvement",strategic_fit:.78,impact:.66,feasibility:.82,risk_control:.72,learning_value:.38,option_value:.34,ethical_resilience:.58,evidence_confidence:.78},OptionScore{name:"Exploratory Learning Pilot",strategic_fit:.62,impact:.58,feasibility:.66,risk_control:.54,learning_value:.86,option_value:.78,ethical_resilience:.64,evidence_confidence:.52},OptionScore{name:"Transformational Platform Bet",strategic_fit:.70,impact:.88,feasibility:.42,risk_control:.32,learning_value:.72,option_value:.62,ethical_resilience:.46,evidence_confidence:.44}]; for o in options{println!("{} | score {:.3} | confidence-adjusted {:.3}",o.name,score(&o),score(&o)*o.evidence_confidence)}}
